local _, WFI = ...
WFI.Data.add("quest", {
  [96031] = { "Campeggio 101: Leatherworking", nil, "Hai imparato la conciatura. Buon per te, {class}. Credo di conoscere qualcuno che può insegnarti a farti una tenda che ti terrà al fresco nei giorni caldi e all'asciutto nei giorni di pioggia.\n\nCon una buona tenda sopra la testa, ti assicurerai tutto il riposo necessario per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, nil, 0x86e620e9, nil, nil, ".m.mm" },
  [96044] = { "Campeggio 101: Blacksmithing", "Parla con Tognus Flintfire, a Kharanos, per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi sei <diventato/diventata> fabbro. Ottima scelta, se vuoi essere <sicuro/sicura> che le tue lame non perdano mai il filo.\n\nCredo di conoscere qualcuno che può aiutarti insegnandoti a creare una Sharpening Wheel. Portane una al tuo accampamento e tutti i guerrieri e i ladri della zona faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0xcccec145, 0x469a706e, nil, nil, "...mm" },
  [96045] = { "Campeggio 101: Alchemy", nil, nil, nil, nil, 0x32f4ba12, nil, nil, nil, nil, ".mmmm" },
  [96046] = { "Campeggio 101: Mining", "Parla con Yarr Hammerstone a Kharanos per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'estrazione mineraria non sarà il mestiere più affascinante, ma è un lavoro onesto e una buona professione da esplorare.\n\nConosco qualcuno che può insegnarti a creare una Lodestone per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada si radunerà volentieri attorno al tuo fuoco per assorbire quella \"spinta\" in più che può dare alle sue capacità in combattimento.", nil, nil, 0xa8fe12f3, 0xc44564fc, 0x8ef0fff6, nil, nil, "...mm" },
  [96047] = { "Campeggio 101: First Aid", nil, "Quindi ti sei <dedicato/dedicata> al First Aid? Una scelta onorevole... e pragmatica per un {class}.\n\nCredo di conoscere qualcuno che può insegnarti a creare un First Aid Kit per il tuo accampamento. Le ferite sono una realtà nel mondo dell'avventura, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, nil, 0x6e7c255b, nil, 0x32ff3188, nil, nil, ".m.mm" },
  [96050] = { "Campeggio 101: Fishing", "Parla con Paxton Ganter vicino all'Iceflow Lake, a Dun Morogh, per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo penseresti, ma la tua abilità di pescatore può tornare utile all'accampamento.\n\nConosco qualcuno che può insegnarti a creare una Fish Bowl per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e sono sicuro che le tue capacità in combattimento ne risentiranno in meglio.", nil, "Ecco fatto, ora puoi creare una Fish Bowl tutto tuo. Alla maggior parte della gente non piace che si montino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0xe0c1c700, 0x475dee95, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [96055] = { "Campeggio 101: Herbalism", nil, "Mi sembra che tu abbia acquisito una certa abilità in erboristeria. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e incantatori, e un Incense Candle può dare una spinta che chi usa la magia apprezzerà di sicuro.", nil, "Ecco fatto: ora puoi creare il tuo Incense Candle. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0xd7cde71c, nil, 0xe0048777, nil, 0x52608ebe, ".m.m." },
  [96056] = { "Campeggio 101: Skinning", nil, "Saper ricavare con abilità pelli e cuoio dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nCredo di conoscere qualcuno che può insegnarti a creare una Camp Chair per il tuo accampamento. A volte è importante semplicemente riposarsi, e puoi usare un po' delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a essere al massimo della forma e a colpire dove conta la prossima volta che ti troverai in una zuffa.", nil, nil, 0x14236b38, nil, 0x1755b1ba, nil, nil, ".m.mm" },
  [96057] = { "Campeggio 101: Tailoring", "Parla con Uthrar Threx a Ironforge per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "La sartoria è un mestiere sorprendentemente potente su cui investire, e sono sicuro che ti servirà bene.\n\nConosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento, se ne hai l'abilità. Ispirazione e morale sono fondamentali per il successo su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, "Ecco fatto, ora puoi creare un Rallying Banner tutto tuo. Alla maggior parte della gente non piace che si montino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nell'arte culinaria per impararne le basi.", 0xde7f398c, 0xf651cfe5, 0x49663bd1, nil, 0x8e312c30, "...m." },
  [96058] = { "Campeggio 101: Engineering", "Parla con Bronk Guzzlegear a Kharanos per imparare a creare un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventare ogni sorta di aggeggi, robot e bombe, per divertimento e per profitto.\n\nConosco qualcuno che può insegnarti a creare un Reagent Bot per il tuo accampamento. Questo utile automa può tenerti ben rifornito, così che tu e i tuoi alleati non restiate mai senza i materiali necessari per alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0x1d43c051, 0x549b28c0, nil, nil, "...mm" },
  [96059] = { "Campeggio 101: Enchanting", nil, nil, nil, nil, 0x2e9b8c15, nil, nil, nil, nil, ".mmmm" },
  [96102] = { "Campeggio 101: Tailoring", nil, "La sartoria è un mestiere sorprendentemente potente su cui investire, e sono sicuro che ti servirà bene.\n\nConosco qualcuno che può insegnarti a creare un Faction Banner per il tuo accampamento, se ne hai l'abilità. Ispirazione e morale sono fondamentali per il successo su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, nil, 0x49663bd1, nil, nil, ".m.mm" },
  [96137] = { nil, "Sconfiggi $N1 Young Black Ravager e $N2 Black Ravager, poi torna da Sirra Von'Indi, a Darkshire, per altre informazioni.", "Un piccolo pugnale appartenuto a Ira, ranger autoproclamata che teneva sicure le foreste impedendo alle belve che le abitavano di attaccare i viandanti.\n\nCon lo spirito di Ira che vaga ancora per i boschi, forse la sua faccenda in sospeso era liberare la foresta dai worg che continuano a mietere vittime.", nil, nil, nil, 0x8b815c85, 0x2af9a1e7, nil, nil, "m..mm" },
  [96138] = { nil, "Sconfiggi $N1 Splinter Fist Warrior e $N2 Splinter Fist Taskmaster, poi torna da Sirra Von'Indi, a Darkshire, per altre informazioni.", "Un arco lasciato dallo spirito di Merrick Valor, celebre Watcher che andava fiero di tenere le strade al sicuro dai nemici invasori.\n\nCon lo spirito di Merrick che vaga ancora per le strade, forse la sua faccenda in sospeso era scacciare gli invasori vicino alla sua casa a Raven Hill. Gli ogre a sud della città potrebbero essere ciò che turba il suo spirito.", nil, nil, nil, 0xea183417, 0xd5097423, nil, nil, "m..mm" },
  [96139] = { "La famiglia Valor", "Perlustra Raven Hill in cerca di qualcosa di interessante e torna da Sirra Von'Indi, a Darkshire.", "In tempi bui come questi, è importante ricordare i nostri eroi tanto quanto i nostri nemici. Darkshire non sarebbe ancora in piedi se non fosse per il coraggio di gente come la buona Lady Althea o di coloro che persero la vita a Raven Hill.\n\nHai letto molto su Raven Hill? No, certo che no. La sua storia è stata cancellata insieme alla sua gente. La mia biblioteca, per quanto notevole, ha poco sull'argomento.\n\nSe per caso trovi qualcosa, ti sarei <grato/grata> se lo portassi qui. Quella gente merita di essere ricordata.", "Hai trovato qualcosa? Non ci spero molto.", "Questo tomo sembra parlare della famiglia Valor. Credo di aver sentito parlare di alcuni di loro. Brava gente. Non sono sicuro che meritino un libro intero.\n\nTi farò una copia del tomo. Se durante i tuoi viaggi vedi qualcos'altro che li riguarda, sarò felice di prenderlo.", 0x27a57039, 0x2c2db2c8, 0xb8e94707, 0xd0323cfc, 0xba858917, "....." },
  [96222] = { nil, "Porta il Maraudine Key Fragment a Umarak, a Desolace.", "Mentre la guerra infuria in tutta la regione, i centauri Maraudine dominano incontrastati la Valley of Spears. Temo che col tempo diventeranno insensibili e fomenteranno altri disordini se gli altri clan continueranno a chiudere un occhio sulla loro presenza.\n\nIl Khan Hratha possiede un Maraudine Key Fragment, e lo voglio come strumento di negoziazione. Procurati un bocchino del corno da guerra dai centauri di laggiù e usalo per sfidarlo sulla vetta più alta.\n\nPortami la chiave e avrò una proposta per te.", nil, nil, nil, 0xffb7769a, 0x95b5e8c9, nil, nil, "m..mm" },
  [96243] = { "Il richiamo della terra", "Trova Teo Hammerstorm a Dun Morogh.", "È ora che tu dia ascolto alla terra, <valoroso/valorosa> sciamano. Gli elementi già ti pizzicano la pelle, ma una volta che parlerai con la pietra, il suolo stesso si farà saldo sotto le tue suole... e nella tua anima.\n\nCerca Teo Hammerstorm, nella Coldridge Valley. Lo troverai dentro Anvilmar, una roccaforte forgiata da martello, fuoco e volontà.", nil, nil, 0xe316c17f, 0xf8e81384, 0x13c0eb8d, nil, nil, "...mm" },
  [96339] = { "Ricompensa del retaggio: Replica Ironforge Air Rifle", nil, nil, nil, nil, 0x049ac689, nil, nil, nil, nil, ".mmmm" },
  [96390] = { "Stroncarli sul nascere", "Uccidi $N1 Dark Iron Spies a Dun Morogh.", "Spie Dark Iron si sono infiltrate a Dun Morogh. A quale scopo non posso esserne sicuro, ma è un problema da stroncare sul nascere prima che cresca.\n\nDirigiti verso est, all'Ironband's Compound, e uccidi le spie Dark Iron che trovi lì.", nil, "Questi Dark Iron saranno anche nostri cugini, ma non sono famiglia, questo è certo. Non verso lacrime per le disgrazie che colpiscono quelli che si allontanano troppo da quella loro montagna maledetta.\n\nSperiamo che basti a dissuaderli da altre incursioni in queste terre.", 0x5f38218b, 0x10fb22fa, 0x9db0e0ef, nil, 0xd5731f3e, "...m." },
  [96391] = { "Una mappa misteriosa", "Consegna la Dark Iron Map all'Earthseer Farsen, a Dun Morogh.", "La mappa che hai in mano sembra mostrare una complessa rete di gallerie e strade sotterranee che convergono tutte in un punto proprio sotto Ironforge.\n\nNon puoi essere <sicuro/sicura> di cosa dicano le rune, scritte nella brutta e spigolosa lingua runica dei nani Dark Iron, ma puoi intuire lo scopo di queste gallerie. Mentre leggi la mappa, una folata di vento ti investe e senti debolmente una voce nanica portata da essa. L'Earthseer Farsen deve vedere questa mappa.", "Oh, e questa cos'è?", "A giudicare da questa mappa, sembra proprio che questi Dark Iron stiano pianificando una specie di incursione nelle cripte sotto Ironforge. La banda che hai sbaragliato a est dev'essere una forza di ricognizione.\n\nGrazie per avermela portata. Se ci sbrighiamo, potremmo anticiparli, qualunque sia il loro obiettivo laggiù.", 0x9d9cce92, 0x0559f95b, 0x9898e535, 0x52844eeb, 0x1c2fe859, "....." },
  [96392] = { "La vista di Farsen", "Parla con l'Earthseer Farsen e chiedigli di prestarti la sua vista lontana per osservare la minaccia dei Dark Iron.", "Salute a te, amico. Mi chiamo Earthseer Farsen e sono in visita a Dun Morogh da Aerie Peak. Mentre viaggiavo non ho potuto fare a meno di notare che abbiamo, ehm... un bel problema di nani Dark Iron.\n\nSe hai un momento, posso mostrarti cosa intendo. Ho un po' di magia che dovrebbe fare al caso nostro.", nil, "Lo vedi ora, {class}? Sono fitti come scarafaggi, e sono solo quelli che vediamo dal cielo.\n\nSembri un tipo abbastanza robusto. Che ne dici di un po' di violenza?", 0x9243cd15, 0x987a4089, 0xce20450c, nil, 0xf760c717, "...m." },
  [96393] = { "Incursione nella vecchia Ironforge", "Entra nella Hall of Thanes sotto Old Ironforge e reclama l'Head of Durgen Dirgehammer.", "Raduna degli alleati e scendi nelle caverne sotto Old Ironforge. Entra nella Hall of Thanes e spingiti fino alle cripte inferiori.\n\nIl mio Dark Iron è un po' arrugginito, ma riesco a decifrare un nome: un certo Durgen Dirgehammer. Probabilmente è lui il comandante. Prendi la sua testa e consegnala a re Magni Bronzebeard.\n\nAh, e quando lo fai, digli che il suo vecchio amico Farsen lo saluta!", "Di cosa hai bisogno, cittadino?", "Un'incursione dei Dark Iron... proprio sotto i nostri piedi? Be', sono sollevato di sapere che il comandante Dark Iron è stato eliminato.\n\nLe guardie scenderanno a ripulire il resto della marmaglia. Faremo sigillare le brecce e rinforzare i livelli inferiori, così che nessun'altra incursione sia possibile.\n\nGrazie per il tuo servizio a Ironforge, {class}. Prendi questo come piccolo segno della mia gratitudine. Ah, e se rivedi quel vecchio Wildhammer abbracciasassi di Farsen, digli di venirmi a trovare come si deve.", 0x48866402, 0xe0bec594, 0xa08604c5, 0xa75dc075, 0x1c39cb14, "....." },
  [96394] = { "I morti senza pace", "Uccidi $N1 Enraged Apparition e $N2 Tormented Soul e dai pace allo spirito di Anvilmar.", "Qualcosa ha disturbato le tombe giù nella Hall of Thanes, e strani rumori sono stati uditi provenire dal profondo delle cripte. Gli spiriti dei morti hanno il sonno leggero, e qualunque cosa stia succedendo laggiù sembra averli spaventati.\n\nScendi e vedi cosa puoi fare per noi. Se qualcuno dei morti è sveglio... be', rimettilo a dormire!", nil, "Ah, bene, allora è fatta. Non posso permettere che gli altri custodi si rifiutino di entrare nella sala per fare il loro dovere a causa di \"fantasmi\" e \"morti arrabbiati\", no?", 0x69066003, 0x6a43847e, 0xd9e1bd9c, nil, 0xd8017bd3, "...m." },
  [96395] = { "Un antico rancore", "Dai pace allo spirito di Faldrim Anvilmar, poi torna dal Ghostly Attendant nella Hall of Thanes.", "Il... Thane... il mio possente... Thane... ha... bisogno... di riposare.\n\nTi prego... aiutalo... aiutalo... a riposare...\n\nConsumato... da... un antico... rancore... Nessun... riposo...", "<La figura spettrale fissa il vuoto oltre te. La sua bocca si muove, ma si odono solo rantoli bassi e incomprensibili.>", "Il mio... Thane... lui... riposa... sì... riposa.\n\nGrazie...\n\nIo... riposo...", 0x372fadb2, 0xf47ad935, 0x22f3d060, 0x36b0ce0b, 0x80ede96a, "....." },
  [96408] = { "Una visita a Dun Morogh", "Indaga sull'accampamento che domina la Gol'Bolar Quarry.", "Ieri notte uno dei nostri montanari ha avvistato un fuoco da campo su un pendio a est. Sembra trovarsi piuttosto in alto, a dominare la Gol'Bolar Quarry.\n\nProbabilmente non è niente, ma vorrei che andassi a controllare quell'accampamento. Se sono amichevoli, nessun danno. Se non lo sono... be', sai cosa fare.", nil, "Salute, amico. Come va?", 0x7b3a9976, 0x89d2ded4, 0x1a6a0853, nil, 0x9c8725d7, "...m." },
  [96626] = { "Campeggio 101: Cooking", nil, "Quindi vuoi saperne di più sul campeggio, eh? Buon per te, {class}. Il primo passo che ogni avventuriero deve fare è diventare <cuoco/cuoca> e imparare ad accendere un fuoco da campo.\n\nCucinare non significa solo preparare cibi gustosi. È anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai disporre troppi arredi intorno.\n\nAumenta la tua abilità in cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti da altri istruttori di professioni, se sei <esperto/esperta> nelle loro abilità.", 0x61f383d0, nil, 0x611be1a4, 0x20282ef3, 0x4d6e308e, ".m..." },
  [96627] = { "L'avventuriero", nil, nil, nil, nil, 0x1afc3318, nil, nil, nil, nil, ".mmmm" },
  [96628] = { "L'avventuriero", nil, nil, "Sei qui per imparare a campeggiare nelle terre selvagge?", nil, 0x1afc3318, nil, nil, 0xf7a7f9bd, nil, ".mm.m" },
  [96629] = { "Campeggio 101: Cooking", nil, "Quindi vuoi saperne di più sul campeggio, eh? Buon per te, {class}. Il primo passo che ogni avventuriero deve fare è diventare <cuoco/cuoca> e imparare ad accendere un fuoco da campo.\n\nCucinare non significa solo preparare cibi gustosi. È anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai disporre troppi arredi intorno.\n\nAumenta la tua abilità in cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti da altri istruttori di professioni, se sei <esperto/esperta> nelle loro abilità.", 0x61f383d0, nil, 0x611be1a4, 0x20282ef3, 0x4d6e308e, ".m..." },
  [96630] = { "L'avventuriero", "Porta il diario a Lyreena Duskblade, vicino a Dolanaar.", "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nCi sono diverse annotazioni che parlano di campeggio. Sembra piuttosto... divertente.>", "Sei qui per imparare a campeggiare nelle terre selvagge?", "È il mio diario? Lo stavo cercando da un po'. Grazie, {class}.\n\nEhi, anche tu hai l'aria di chi vive d'avventure. Ti piacerebbe imparare qualcosa sul campeggio?", 0x1afc3318, 0xc5322669, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96634] = { "Campeggio 101: Cooking", "Parla con Zarrin, a Dolanaar, per imparare a diventare <cuoco/cuoca>.", "Quindi vuoi saperne di più sul campeggio, eh? Buon per te, {class}. Il primo passo che ogni avventuriero deve fare è diventare <cuoco/cuoca> e imparare ad accendere un fuoco da campo.\n\nCucinare non significa solo preparare cibi gustosi. È anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai disporre troppi arredi intorno.\n\nAumenta la tua abilità in cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti da altri istruttori di professioni, se sei <esperto/esperta> nelle loro abilità.", 0x61f383d0, 0xa03560df, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96638] = { "L'avventuriero", nil, nil, nil, nil, 0x1afc3318, nil, nil, nil, nil, ".mmmm" },
  [96646] = { "Campeggio 101: Cooking", nil, "Quindi vuoi saperne di più sul campeggio, eh? Buon per te, {class}. Il primo passo che ogni avventuriero deve fare è diventare <cuoco/cuoca> e imparare ad accendere un fuoco da campo.\n\nCucinare non significa solo preparare cibi gustosi. È anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai disporre troppi arredi intorno.\n\nAumenta la tua abilità in cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti da altri istruttori di professioni, se sei <esperto/esperta> nelle loro abilità.", 0x61f383d0, nil, 0x611be1a4, 0x20282ef3, 0x4d6e308e, ".m..." },
  [96652] = { "L'avventuriero", nil, "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nCi sono diverse annotazioni che parlano di campeggio. Sembra piuttosto... divertente.>", "Sei qui per imparare a campeggiare nelle terre selvagge?", "È il mio diario? Lo stavo cercando da un po'. Grazie, {class}.\n\nEhi, anche tu hai l'aria di chi vive d'avventure. Ti piacerebbe imparare qualcosa sul campeggio?", 0x1afc3318, nil, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, ".m..." },
  [96655] = { "Campeggio 101: Cooking", nil, "Quindi vuoi saperne di più sul campeggio, eh? Buon per te, {class}. Il primo passo che ogni avventuriero deve fare è diventare <cuoco/cuoca> e imparare ad accendere un fuoco da campo.\n\nCucinare non significa solo preparare cibi gustosi. È anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai disporre troppi arredi intorno.\n\nAumenta la tua abilità in cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti da altri istruttori di professioni, se sei <esperto/esperta> nelle loro abilità.", 0x61f383d0, nil, 0x611be1a4, nil, 0x4d6e308e, ".m.m." },
  [96656] = { "L'avventuriero", nil, nil, nil, nil, 0x1afc3318, nil, nil, nil, nil, ".mmmm" },
  [96658] = { "Campeggio 101: Cooking", nil, "Quindi vuoi saperne di più sul campeggio, eh? Buon per te, {class}. Il primo passo che ogni avventuriero deve fare è diventare <cuoco/cuoca> e imparare ad accendere un fuoco da campo.\n\nCucinare non significa solo preparare cibi gustosi. È anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai disporre troppi arredi intorno.\n\nAumenta la tua abilità in cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti da altri istruttori di professioni, se sei <esperto/esperta> nelle loro abilità.", 0x61f383d0, nil, 0x611be1a4, nil, 0x4d6e308e, ".m.m." },
  [96659] = { "L'avventuriero", nil, nil, "Sei qui per imparare a campeggiare nelle terre selvagge?", nil, 0x1afc3318, nil, nil, 0xf7a7f9bd, nil, ".mm.m" },
  [96661] = { "Campeggio 101: Cooking", nil, "Quindi vuoi saperne di più sul campeggio, eh? Buon per te, {class}. Il primo passo che ogni avventuriero deve fare è diventare <cuoco/cuoca> e imparare ad accendere un fuoco da campo.\n\nCucinare non significa solo preparare cibi gustosi. È anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai disporre troppi arredi intorno.\n\nAumenta la tua abilità in cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti da altri istruttori di professioni, se sei <esperto/esperta> nelle loro abilità.", 0x61f383d0, nil, 0x611be1a4, nil, 0x4d6e308e, ".m.m." },
  [96779] = { "Sabotaggio del Syndicate", "Trova Lord Tomas dentro la Durnholde Keep, nelle Hillsbrad Foothills, e uccidilo. Poi torna da Myrokos Silentform.", "A volte, {race}, un solo taglio nel punto giusto basta ad abbattere un nemico. Lo stesso vale spesso per le organizzazioni.\n\nI nostri agenti hanno individuato un bersaglio chiave tra i ranghi del Syndicate: un uomo di nome Lord Tomas.\n\nHa un ruolo fondamentale nel funzionamento della Durnholde Keep, nelle Hillsbrad Foothills. Se desideri servire Ravenholdt, va' a Durnholde ed eliminalo. Più rapidamente e silenziosamente, meglio è.", nil, nil, 0x12459469, 0xd843986f, 0xd52e350a, nil, nil, "...mm" },
  [96877] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
})
